head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL05034";
scwin.NEWSEL = 4;
scwin.form = null;

// as-is 공용 상수 — 셸이 js/elw.js 를 싣지 않아 화면에 선언한다(KRX 합의 대상).

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05034.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_bzCd", fn: function(){ return ((dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '0' || (dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '2'); } }, { id: "if_bzCd_2", fn: function(){ return ((dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '1' || (dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '3'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.form = (document.ElwForm || { elements: [] });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05034.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_NewSearch();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_ElwPageUsrSearch_onclick
 * @description 「목록보기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ElwPageUsrSearch_onclick = async function(e){
    try {
        await scwin.elwPageUsrSearch()
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil05034.btn_ElwPageUsrSearch_onclick" });
    }
};

/**
 * @method
 * @name __ev_2_btn_ElwPageUsrSearch_onclick
 * @description __ev_2_btn_ElwPageUsrSearch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__ev_2_btn_ElwPageUsrSearch_onclick = async function(e){
    try {
        await scwin.elwPageUsrSearch()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05034.__ev_2_btn_ElwPageUsrSearch_onclick' }); }
};

/**
 * @method
 * @name grd_readDataVOArrayAttach_oncellclick
 * @description grd_readDataVOArrayAttach 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_readDataVOArrayAttach_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_readDataVOArrayAttach');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_readDataVOArrayAttach */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.fileDown(r["bzProcsNo"], r["elwAttachSeq"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_readDataVOArrayAttach.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_NewSearch
 * @description New Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_NewSearch = async function () {
    const sbmOptions = {
        id: "tx_fn_NewSearch",
        method: "post",
        action: "/list/elw.do",
        ref: "dma_NewSearchReq",
        target: "dlt_readDataVOArrayAttach=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function (action) {
    try { return await $c.data.downFile(action ?? "/common/irDataFileDown.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} elwAttachSeq elwAttachSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (bzProcsNo, elwAttachSeq) {
    $c.util.getComponent('dma_FileDownReq').set('bzProcsNo', bzProcsNo);
    $c.util.getComponent('dma_FileDownReq').set('elwAttachSeq', elwAttachSeq);
    $c.util.getComponent('dma_FileDownReq').set('method', 'searchElwFileDown');
    await scwin.tx_fn_FileDown('/common/irDataFileDown.do');
};

/**
 * @method
 * @name newSearch
 * @description new Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newSearch = async function () {
    $c.util.getComponent("dma_FileDownReq").set("transKind", scwin.NEWSEL);
    scwin.form.action = '/list/elw.do';
    $c.util.getComponent('dma_FileDownReq').set('method', 'searchElw');
    await scwin.tx_fn_NewSearch();
};

/**
 * @method
 * @name elwPageUsrSearch
 * @description elw Page Usr Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.elwPageUsrSearch = async function () {
    $c.util.getComponent("dma_FileDownReq").set("bzCd", BZ_USRLST);

    if( scwin.form.isuNm != null ) {
        scwin.form.isuNm.value  = "" ;
    }

    scwin.form.action       = '/list/elwPage.do';
    $c.util.getComponent('dma_FileDownReq').set('method', 'elwPageSearch');
    await moveUrl('/list/elw.do', {});

};
